#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* Return the Soundex digit for an upper‑case letter.
   0 is returned for letters that do not map to a digit. */
static int soundex_digit(char c)
{
    switch (c) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default: return 0;
    }
}

/* Compute the Soundex code of a string.
   The result buffer must have room for at least 5 characters
   (4 characters + terminating NUL). */
static void soundex(const char *src, char *dst)
{
    /* first letter, upper‑cased */
    char first = src[0];
    if (islower((unsigned char)first))
        first = (char)toupper((unsigned char)first);
    dst[0] = first;

    int prev_digit = soundex_digit(first);
    int count = 0;               /* how many digits have been stored */
    size_t i = 1;                /* start with the second character */

    while (src[i] != '\0' && count < 3) {
        char ch = src[i];
        ++i;

        if (!isalpha((unsigned char)ch))
            continue;            /* ignore non‑letters */

        if (ch == 'H' || ch == 'W' || ch == 'h' || ch == 'w')
            continue;            /* H and W are ignored */

        if (islower((unsigned char)ch))
            ch = (char)toupper((unsigned char)ch);

        int digit = soundex_digit(ch);
        if (digit == 0)
            continue;            /* vowels etc. produce no digit */

        if (digit == prev_digit)
            continue;            /* suppress duplicate codes */

        dst[1 + count] = (char)('0' + digit);
        ++count;
        prev_digit = digit;
    }

    /* pad with '0' up to length 4 */
    while (count < 3) {
        dst[1 + count] = '0';
        ++count;
    }
    dst[4] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 2 || argv[1][0] == '\0') {
        puts("EMPTY");
        return 0;
    }

    char code[5];
    soundex(argv[1], code);
    puts(code);
    return 0;
}
